// Prices come from /api/stocks (Yahoo Finance chart API, daily data).
// Symbols that return no data are skipped silently — never faked.
// All trading here is DEMO/paper-trading only.

export type StockRegion =
  'in_nse' | 'in_bse' | 'us' | 'ca' | 'sg' | 'uk' | 'de' | 'fr' | 'nl' | 'ch' | 'dk' | 'ie' | 'pt' | 'be' | 'jp' | 'hk' | 'au' | 'kr' | 'tw' | 'br' | 'za' | 'nz' | 'no' | 'se' | 'es' | 'it' | 'at' | 'gr' | 'fi' | 'pl' | 'cz' | 'hu' | 'ro' | 'mx' | 'ar' | 'cl' | 'co' | 'pe' | 'eg' | 'th' | 'my' | 'id' | 'ph' | 'vn' | 'cn' | 'ru' | 'tr' | 'il' | 'sa' | 'pk' | 'ae' | 'qa' | 'kw' | 'ng' | 'ke' | 'bd' | 'lk';

export type Stock = {
  symbol: string; // display ticker, e.g. 'RELIANCE'
  yahoo: string; // Yahoo Finance symbol, e.g. 'RELIANCE.NS'
  name: string;
  region: StockRegion;
  exchange: string;
  tv: string; // TradingView symbol, e.g. 'NSE:RELIANCE'
  currency: string;
  decimals: number;
};

